- bool private _initializing;
- event Initialized(uint8 version);
- modifier initializer() {
    bool isTopLevelCall = !_initializing;
    require(
        (isTopLevelCall && _initialized < 1) ||
        (!AddressUpgradeable.isContract(address(this)) && _initialized == 1),
        "Initializable: contract is already initialized"
    );
    _initialized = 1;
    if (isTopLevelCall) { _initializing = true; }
    _;
    if (isTopLevelCall) { _initializing = false; emit Initialized(1); }
}
- reinitializer(uint8 version) require(!_initializing && _initialized < version)
- onlyInitializing require(_initializing)
- _disableInitializers internal virtual require(!_initializing); if (_initialized != type(uint8).max) { _initialized = type(uint8).max; emit Initialized(type(uint8).max); }
- _getInitializedVersion view returns _initialized
- _isInitializing view returns _initializing.

